            self.hash = hash;
            self.params = params;
            self.redirect_path = redirect_path;
            self.query_string = query_string;
    }

pub inline fn hasParams(self: *const Match) bool {
            return (self.params.len > 0);
    }

pub fn paramsIterator(self: *const Match) PathnameScanner {
            return PathnameScanner.init(self.pathname, self.name, self.params);
    }

pub fn nameWithBasename(file_path: []const u8, dir: []const u8) []const u8 {
            var result_name = file_path;
            _ = &result_name;
            if (cp_index_of(strings, result_name)) |i| {
                _ = &i;
                result_name = result_name[(i + dir.len)..];
            }
            return result_name[0..(result_name.len - std.fs.path.extension(result_name).len)];
    }

pub fn pathnameWithoutLeadingSlash(self: *const Match) []const u8 {
            return std.mem.trimLeft(u8, self.pathname, "/");
    }
};

pub const PathString = bun.PathString;
pub const RoutePathInt = route_types.RoutePathInt;
pub const TinyPtr = route_types.TinyPtr;
pub const WindowsAbsPath = route_types.WindowsAbsPath;
pub const AbsPathType = route_types.AbsPathType;
pub const Pattern = route_types.Pattern;
pub const Param = ParamMapModule.Param;
pub const ParamListPtr = ParamMapModule.ParamListPtr;
pub const MatchContextTypePtr = *MatchContextType;
